#!/bin/sh
# I428: a YM file plays through `selecta-cli render` as a RENDER-kind replayer (ym, StSound). One reachability test
# through the product entry point; the sentinel is the `replayer=ym` line of render. Fixture:
# tests/m3/fixtures/ym_test.ym (generated by make_ym_fixture.py, 12 s of tone, source in ym_test.ym.SOURCE), so the
# 10 s asked for end before the song does. Asserts: the plugin ran, the WAV is not silent (energy of the 16-bit
# samples) and the rendered frame count equals 10 s +-1% at the output rate.
# usage: ym_decode.sh <selecta-cli> <ym-file>
set -u
cli=$1
ym=$2
field() { printf '%s\n' "$1" | tr ' ' '\n' | sed -n "s/^$2=//p" | head -1; }
fail() { echo "FAIL: $*"; exit 1; }
rate=44100
rm -f fd_ym.wav
out=$("$cli" render "$ym" --output fd_ym.wav --seconds 10 --rate "$rate" 2>/dev/null) || fail "render failed"
[ "$(field "$out" replayer)" = "ym" ] || fail "replayer=$(field "$out" replayer), want ym"
got=$(field "$out" rendered_frames)
awk -v g="$got" -v w=$((rate * 10)) 'BEGIN { d = g - w; if (d < 0) d = -d; exit !(d <= w * 0.01) }' ||
    fail "rendered_frames=$got, want $((rate * 10)) +-1%"
e=$(od -An -v -t d2 -j 44 fd_ym.wav | tr -s " " "\n" | awk '$1 != "" { s += $1 * $1 } END { printf "%d", s }')
[ "$e" -gt 1000000 ] || fail "silent output (energy $e)"
echo ym_decode_ok
